#!/usr/bin/env bash
set -euo pipefail
if test "$#" -ne 5; then echo "usage: evaluate.sh ROOT CORE_RECEIPTS FACTS OUTPUT SUBJECT_SHA" >&2; exit 64; fi
root=$1; core_receipts=$2; facts=$3; output=$4; subject_sha=$5; denominator="$root/contracts/connector-denominator-v1.json"
jq -S -n --slurpfile denominator "$denominator" --slurpfile core "$core_receipts" --slurpfile facts "$facts" --arg subject_sha "$subject_sha" '
  $denominator[0] as $d|$facts[0] as $f|($core[0]|map({key:.selector.name,value:.})|from_entries) as $receipts|
  def strip:del(.closed_reason,.unknown_reason,.refuted_reason,.restore_operation);
  def cr($cell):($receipts[$cell.activity]//null) as $r|if $r==null then {decision:"UNKNOWN",state:"UNKNOWN",stage:"RESOLUTION",step:"RESOLVE_ACTIVITY_CARDINALITY",reason:"CORE_ACTIVITY_RESOLUTION_RECEIPT_UNAVAILABLE",unknown_class:"DIRECT_MISSING",next_operation:"PROVIDE_CORE_ACTIVITY_RESOLUTION_RECEIPT",activity_occurrences:0} elif $r.decision=="CLOSED" and $r.occurrences==1 and $r.claim.state=="CLOSED" and $r.claim.reason=="ACTIVITY_UNIQUELY_RESOLVED" then {decision:"CLOSED",state:"CLOSED",stage:"RESOLUTION",step:"RESOLVE_ACTIVITY_CARDINALITY",reason:"FACT_OBSERVED",unknown_class:null,next_operation:"NONE",activity_occurrences:1} elif $r.decision=="UNKNOWN" then {decision:$r.decision,state:"UNKNOWN",stage:"RESOLUTION",step:"RESOLVE_ACTIVITY_CARDINALITY",reason:($r.claim.reason//"CORE_ACTIVITY_RESOLUTION_UNKNOWN"),unknown_class:($r.claim.unknown_class//"DIRECT_MISSING"),next_operation:($r.claim.next_operation//"RESOLVE_CORE_ACTIVITY"),activity_occurrences:($r.occurrences//0)} else {decision:($r.decision//"UNAVAILABLE"),state:"REFUTED",stage:"RESOLUTION",step:"RESOLVE_ACTIVITY_CARDINALITY",reason:"UNRECOGNIZED_CORE_ACTIVITY_RESOLUTION_DECISION",unknown_class:null,next_operation:"RESTORE_CORE_ACTIVITY_RESOLUTION_RECEIPT",activity_occurrences:($r.occurrences//0)} end;
  def fact($id):if $id=="RELEASED_GOOO_IDENTITY" then $f.core_release_verified elif $id=="PROMOTION_RELEASE_IDENTITY" then $f.promotion.identity_verified elif $id=="ELIGIBLE_PROMOTION" then ($f.promotion.decision=="CONNECTOR_PROMOTION_ELIGIBLE" and $f.promotion.state=="ELIGIBLE") elif $id=="DOMAIN_RELEASE_IDENTITIES" then $f.domain_releases.identity_verified==3 elif $id=="CANONICAL_INPUT_BUNDLES" then (if $f.input.bundles<3 then null else $f.input.bundles==3 end) elif $id=="PORTFOLIO_NODES" then $f.output.node_graph_consistent elif $id=="PORTFOLIO_EDGES" then $f.output.edge_graph_consistent elif $id=="SHARED_SPECIFICATION_ANCHOR" then $f.output.shared_specification_anchors==1 elif $id=="UNKNOWN_RELATIONS" then $f.output.unknown_tuples_complete elif $id=="DETERMINISTIC_REPLAY" then ($f.conformance!=null and ([$f.conformance.checks[]|select(.id=="DETERMINISTIC_REPLAY" and .state=="CLOSED")]|length)==1 and $f.runtime.deterministic_replay==true) elif $id=="READ_ONLY_CHECKSUM_EFFECT" then ($f.conformance.decision=="CONFORMANT" and $f.checksum_guard.decision=="FAIL_CLOSED" and $f.checksum_guard.claim.reason=="SHA256_CHECKSUM_MISMATCH" and $f.runtime.repository.writes==0 and $f.contract.external_required_gates==0 and $f.runtime.local_tests_run==0) elif $id=="CONNECTOR_DECISION" then ($f.connector_decision.state=="CLOSED") else null end;
  def direct($cell):(cr($cell)) as $core|if $core.state=="REFUTED" then ($cell|strip)+{state:"REFUTED",resolution:"EXACT",stage:$core.stage,step:$core.step,reason:$core.reason,next_operation:$core.next_operation,unknown_class:null,blocked_by:[],core_resolution:$core} elif $core.state=="UNKNOWN" then ($cell|strip)+{state:"UNKNOWN",resolution:"PREREQUISITE_CLASS",stage:$core.stage,step:$core.step,reason:$core.reason,next_operation:$core.next_operation,unknown_class:$core.unknown_class,blocked_by:[],core_resolution:$core} elif $cell.id=="CONNECTOR_DECISION" and $f.connector_decision.state=="UNKNOWN" then ($cell|strip)+{state:"UNKNOWN",resolution:"PREREQUISITE_CLASS",stage:$f.connector_decision.stage,step:$f.connector_decision.step,reason:$f.connector_decision.reason,next_operation:$f.connector_decision.next_operation,unknown_class:$f.connector_decision.unknown_class,blocked_by:[],core_resolution:$core} elif fact($cell.id)==true then ($cell|strip)+{state:"CLOSED",resolution:"EXACT",reason:$cell.closed_reason,next_operation:"NONE",unknown_class:null,blocked_by:[],core_resolution:$core} elif fact($cell.id)==null then ($cell|strip)+{state:"UNKNOWN",resolution:"PREREQUISITE_CLASS",reason:$cell.unknown_reason,next_operation:$cell.next_operation,unknown_class:"DIRECT_MISSING",blocked_by:[],core_resolution:$core} else ($cell|strip)+{state:"REFUTED",resolution:"EXACT",reason:$cell.refuted_reason,next_operation:$cell.restore_operation,unknown_class:null,blocked_by:[],core_resolution:$core} end;
  (reduce $d.cells[] as $cell ([];. as $prior|(direct($cell)) as $candidate|([$prior[]|.id as $id|select(($cell.depends_on|index($id))!=null)|select(.state=="REFUTED")]) as $rdeps|([$prior[]|.id as $id|select(($cell.depends_on|index($id))!=null)|select(.state=="UNKNOWN")]) as $udeps|if $candidate.state=="REFUTED" then .+[$candidate] elif ($rdeps|length)>0 then .+[($candidate+{state:"REFUTED",resolution:"EXACT",reason:"DEPENDENCY_REFUTED",next_operation:"RESOLVE_REFUTED_PREDECESSORS",unknown_class:null,blocked_by:[$rdeps[].id]})] elif $candidate.state=="UNKNOWN" then .+[$candidate] elif ($udeps|length)>0 then .+[($candidate+{state:"UNKNOWN",resolution:"PREREQUISITE_CLASS",reason:"DEPENDENCY_UNKNOWN",next_operation:"RESOLVE_UNKNOWN_PREDECESSORS",unknown_class:"DEPENDENCY",blocked_by:[$udeps[].id]})] else .+[$candidate] end)) as $cells|
  ([$cells[]|select(.state=="CLOSED")]|length) as $closed|([$cells[]|select(.state=="UNKNOWN")]|length) as $unknown|([$cells[]|select(.state=="REFUTED")]|length) as $refuted|([$cells[]|select(.state!="CLOSED")][0]//null) as $first|
  {schema:"gooo/advisory-connector/report/v1",subject_sha:$subject_sha,decision:(if $refuted>0 then "FAIL_CLOSED" elif $unknown>0 then "INCOMPLETE" else "CONNECTOR_CONFORMANT" end),claim:(if $first==null then {state:"CLOSED",stage:null,step:null,reason:"ADVISORY_CONNECTOR_CONFORMANT",next_operation:(if $f.public_state=="MAIN_MERGED" then "PUBLISH_IMMUTABLE_CONNECTOR_RELEASE" else "MERGE_CONNECTOR_PR" end),unknown_class:null,blocked_by:[]} else {state:$first.state,stage:$first.stage,step:$first.step,reason:$first.reason,next_operation:$first.next_operation,unknown_class:$first.unknown_class,blocked_by:$first.blocked_by} end),summary:{total:12,closed:$closed,unknown:$unknown,refuted:$refuted,output_files:$f.output.files,nodes:$f.output.nodes,edges:$f.output.edges,unknown_relations:$f.output.unknowns},implementation:{state:$f.public_state,effect:"READ_ONLY",consumer_branches:0,cross_project_required_gates:$f.contract.external_required_gates},cells:$cells,proofs:(["FOUNDATION","COHERENCE","REGRESSION"]|map(. as $p|{choice:$p,closed:([$cells[]|select(.proof_choice==$p and .state=="CLOSED")]|length),total:([$cells[]|select(.proof_choice==$p)]|length)})),indicator_classes:(["OUTCOME","DRIVER","GUARDRAIL"]|map(. as $c|{class:$c,closed:([$cells[]|select(.indicator_class==$c and .state=="CLOSED")]|length),total:([$cells[]|select(.indicator_class==$c)]|length)})),indicators:[{id:"gooo.metric.connector.output-files.v1",value:$f.output.files,total:5,unit:"files",activity:"CloseAdvisoryConnectorDecision"},{id:"gooo.metric.connector.nodes.v1",value:$f.output.nodes,unit:"nodes",activity:"GeneratePortfolioNodes"},{id:"gooo.metric.connector.edges.v1",value:$f.output.edges,total:3,unit:"edges",activity:"GeneratePortfolioEdges"},{id:"gooo.metric.connector.unknown-relations.v1",value:$f.output.unknowns,unit:"relations",activity:"PreserveUnknownRelations"},{id:"gooo.metric.connector.repository-writes.v1",value:$f.runtime.repository.writes,total:0,unit:"writes",activity:"PreserveReadOnlyChecksums"},{id:"gooo.metric.connector.peak-rss.v1",value:$f.runtime.connector.peak_rss_kib,unit:"KiB",activity:"GeneratePortfolioNodes"},{id:"gooo.metric.connector.wall-time.v1",value:$f.runtime.connector.wall_ms,unit:"ms",activity:"GeneratePortfolioEdges"}],runtime:$f.runtime}' > "$output"
